def transform(grid):
    if not grid or not grid[0]:
        return grid

    first_val = grid[0][0]
    L = len(grid[0])

    # Count consecutive first value at start
    consecutive_first = 0
    for val in grid[0]:
        if val == first_val:
            consecutive_first += 1
        else:
            break

    num_rows = L // 2
    output = []

    for i in range(num_rows):
        count_first = consecutive_first + i
        take_start = consecutive_first + i

        row = [first_val] * count_first
        remaining = L - count_first

        for j in range(remaining):
            if take_start + j < L:
                row.append(grid[0][take_start + j])

        output.append(row)

    return output
